package echo

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestTmpBindDataToMap(t *testing.T) {
	e := New()
	req := httptest.NewRequest(http.MethodGet, "/?foo=1&foo=2&bar=3", nil)
	rec := httptest.NewRecorder()
	c := e.NewContext(req, rec)

	m1 := map[string][]string{}
	assert.NoError(t, new(DefaultBinder).BindQueryParams(c, &m1))
	assert.Equal(t, map[string][]string{"foo": {"1", "2"}, "bar": {"3"}}, m1)

	m2 := map[string]string{}
	assert.NoError(t, new(DefaultBinder).BindQueryParams(c, &m2))
	assert.Equal(t, map[string]string{"foo": "1", "bar": "3"}, m2)

	m3 := map[string]interface{}{}
	assert.NoError(t, new(DefaultBinder).BindQueryParams(c, &m3))
	assert.Equal(t, map[string]interface{}{"foo": []string{"1", "2"}, "bar": []string{"3"}}, m3)
}
```
